	protected Encounter read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Encounter" );

		Encounter entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Encounter with primary key" );
		msg.append( encounterId );
		
		EncounterFetchOneSummary fetchOneSummary = new EncounterFetchOneSummary( encounterId );

		try {
			entity = EncounterService.getEncounterInstance().getEncounter( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Encounter " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Encounter.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Encounter." );

		StringBuilder msg = new StringBuilder( "Failed to update a Encounter : " );        
		Encounter entity = read();
		UpdateEncounterCommand command = generateUpdateCommand();
		command.setEncounterId(entity.getEncounterId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Encounter." );

			// for use later on...
			encounterId = entity.getEncounterId();

			EncounterService proxy = EncounterService.getEncounterInstance();  

			proxy.updateEncounter( command ).get();

			LOGGER.info( "-- Successfully saved Encounter - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + encounterId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Encounter.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Encounter." );

		Encounter entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Encounter with id " + encounterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Encounter with id " + encounterId );

			throw e;
		}

		try{
			EncounterService.getEncounterInstance().delete( new DeleteEncounterCommand( entity.getEncounterId() ) ).get();
			LOGGER.info( "-- Successfully deleted Encounter with id " + encounterId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Encounter with id " + encounterId );

			throw e;
		}
	}

	/**
	 * get all Encounters.
	 */
	protected List<Encounter> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Encounters:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Encounter : " );        
		List<Encounter> collection  = new ArrayList<>();

		try {
			// call the static get method on the EncounterService
			collection = EncounterService.getEncounterInstance().getAllEncounter();
			assertNotNull( collection, "An Empty collection of Encounter was incorrectly returned.");
			
			// Now print out the values
			Encounter entity = null;            
			Iterator<Encounter> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getEncounterId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

